function impacted(links, changed) {
  var start = Array.isArray(changed) ? changed : [changed];
  var next = Object.create(null);
  links.forEach(function (l) { (next[l[0]] = next[l[0]] || []).push(l[1]); });
  var seen = Object.create(null), queue = start.slice();
  start.forEach(function (s) { seen[s] = true; });
  var out = [];
  while (queue.length) {
    var cur = queue.shift();
    (next[cur] || []).forEach(function (n) {
      if (seen[n]) return;
      seen[n] = true; out.push(n); queue.push(n);
    });
  }
  return out.sort();
}

function effort(items, hours) {
  return items.reduce(function (s, id) {
    var p = String(id).split('-')[0];
    return s + (Object.prototype.hasOwnProperty.call(hours, p) ? hours[p] : 1);
  }, 0);
}
